        "type": "object",
        "properties": {
          "topic": {
            "type": "string",
            "enum": [
              "cancel",
              "change",
              "baggage",
              "delay_compensation",
              "loyalty",
              "upgrade",
              "hotel_cancel",
              "car_rental_cancel"
            ],
            "description": "The policy topic to look up"
